\begin{hypothesis}[H1: Projection Structure]\label{hyp:H1}
Let $\Hilb$ be a real Hilbert space with inner product $\inner{\cdot}{\cdot}$ and norm $\norm{\cdot}$. Let $\I \subset \Hilb$ be non-empty, closed, and convex.
\end{hypothesis}

\begin{hypothesis}[H2: Contraction Operator]\label{hyp:H2}
Let $K:\Hilb\to\Hilb$ be a bounded linear operator with operator norm $\norm{K}<1$.
\end{hypothesis}

\begin{hypothesis}[H3: Completeness]\label{hyp:H3}
The ambient space $\Hilb$ is complete.
\end{hypothesis}

\begin{remark}[Logical Status of Completeness]
Completeness is already part of the Hilbert-space assumption in H1. H3 records this requirement explicitly for later generalizations; it is not independent of H1 as written. A counterexample in an incomplete inner-product space tests such a generalization, not independence of H3 from H1.
\end{remark}

\begin{hypothesis}[H4: Parameter Compactness]\label{hyp:H4}
Let $\U$ be a compact metric space and let $\Gamma:\U\to\Hilb$ be uniformly continuous.
\end{hypothesis}

\begin{proposition}[Base sufficiency of H1--H4]\label{prop:minimal}
Hypotheses H1--H4 are sufficient for:
\begin{enumerate}[leftmargin=*]
\item existence and uniqueness of the metric projection onto $\I$;
\item strict contraction of the transition operators $T_u$;
\item existence and uniqueness of the fixed point $f_u^\ast$ for each $u\in\U$;
\item compactness of the attractor family $\A^\ast=\{f_u^\ast:u\in\U\}$.
\end{enumerate}
They do not, by themselves, imply parameterwise non-collapse.
\end{proposition}

\begin{definition}[Metric Projection]\label{def:projection}
For $\Psi\in\Hilb$, define the metric projection onto $\I$ by
\[
\aleph(\Psi):=\arg\min_{\Phi\in\I}\norm{\Psi-\Phi}.
\]
\end{definition}

\begin{theorem}[Existence and Uniqueness of Projection]\label{thm:projection}
Under Hypothesis~\ref{hyp:H1}, the projection $\aleph(\Psi)$ exists and is unique for every $\Psi\in\Hilb$.
\end{theorem}

\begin{lemma}[Non-Expansiveness of the Projection]\label{lem:nonexp}
The map $\aleph:\Hilb\to\I$ is non-expansive:
\[
\norm{\aleph(\Psi_1)-\aleph(\Psi_2)}\le \norm{\Psi_1-\Psi_2}
\qquad
\forall \Psi_1,\Psi_2\in\Hilb.
\]
\end{lemma}

\begin{definition}[Transition Operator]\label{def:transition}
For each $u\in\U$, define
\[
T_u(\Psi):=\aleph(K\Psi+\Gamma(u)).
\]
\end{definition}

\begin{theorem}[Contractivity]\label{thm:contraction}
Under Hypotheses~\ref{hyp:H1} and \ref{hyp:H2}, each $T_u$ is a strict contraction with Lipschitz constant at most $\norm{K}$:
\[
\norm{T_u(\Psi_1)-T_u(\Psi_2)}\le \norm{K}\,\norm{\Psi_1-\Psi_2}.
\]
\end{theorem}

\begin{definition}[Attractor Family]\label{def:attractor}
Define the attractor family
\[
\A^\ast:=\{f_u^\ast:u\in\U\}.
\]
\end{definition}

\begin{theorem}[Compactness of the Attractor Family]\label{thm:compactness}
Under Hypotheses~\ref{hyp:H1}--\ref{hyp:H4}, the set $\A^\ast$ is compact in $\Hilb$.
\end{theorem}

\begin{definition}[Constant Subspace]
Whenever the ambient realization distinguishes constant elements, let $\mathcal{N}\subset\Hilb$ denote the closed subspace of constants.
\end{definition}

\begin{hypothesis}[H5: No Constant Fixed Points]\label{hyp:H5}
For every parameter $u\in\U$ and every constant element $c\in\mathcal{N}$,
\[
T_u(c)\neq c.
\]
\end{hypothesis}

\begin{theorem}[Structural Non-Collapsibility]\label{thm:noncollapse}
Under Hypotheses~\ref{hyp:H1}--\ref{hyp:H5}, the family is parameterwise non-collapsible:
\[
f_u^\ast\notin\mathcal{N}
\qquad
\forall u\in\U.
\]
\end{theorem}

\begin{remark}[What H5 does not say]
Hypothesis~\ref{hyp:H5} is parameterwise. It does not merely say that \emph{some} parameter breaks constant collapse. It excludes constant fixed points for \emph{every} parameter. This is exactly the quantifier strength needed for Theorem~\ref{thm:noncollapse}.
\end{remark}

\begin{proposition}[H5 Is Not Implied by H1--H4]\label{prop:h5-not-derived}
There exists a family satisfying H1--H4 for which H5 fails and its unique equilibrium is constant. There also exists a family satisfying H1--H4 for which H5 holds with a positive uniform distance of the equilibria from the constant subspace.
\end{proposition}

\begin{remark}[Typing discipline]
No unembedded element of $E$ is treated as an element of $\mathcal{B}$. The embedding $j$ is always written explicitly. This removes the earlier type leak in which a disk in $E$ was silently treated as a subset of a function space.
\end{remark}

\begin{lemma}[The Disk Projection is Non-Expansive]\label{lem:disk-projection}
For all $v,w\in E$,
\[
\norm{P_E(v)-P_E(w)}_2\le \norm{v-w}_2.
\]
\end{lemma}

\begin{proposition}[Typed Non-Vacuity of the Computable Model]\label{prop:Q3verify}
The embedded constant-disk Golden Mean model is a fully typed, non-vacuous witness of the transition grammar:
\begin{enumerate}[leftmargin=*]
\item every operator has explicit domain and codomain;
\item the transition map $T_u$ is well-defined on $\mathcal{B}$;
\item the family admits unique fixed points and a compact parameter image;
\item the state contraction bound is explicit and computable.
\end{enumerate}
\end{proposition}

\begin{remark}[Why this witness does not certify H5]
The image of $T_u$ lies in the constant subspace $\mathcal{I}_{\mathrm c}$. Therefore its fixed point is constant by construction. This witness is correct and useful for typing and state spectral analysis, but it cannot certify the parameterwise anti-constant hypothesis H5 from Section~\ref{sec:parameterwise-noncollapse}.
\end{remark}

\begin{proposition}[Separate Witness for H5]
The family $\{T_u^{\mathrm{ac}}\}_{u\in\U}$ satisfies Hypotheses~\ref{hyp:H1}--\ref{hyp:H5} of Section~1.
\end{proposition}

\begin{remark}
BaseCore therefore distinguishes two roles cleanly: the Golden Mean witness certifies typed operator correctness and state contraction; the affine anti-collapse witness certifies the stronger H5 burden needed for parameterwise non-collapse.
\end{remark}

\begin{theorem}[Relaxation-Time Bound]\label{thm:relaxation}
Under the hypotheses of Theorem~\ref{thm:spectrum}, any discrete-to-continuous relaxation convention of the form
\[
\tau_{\mathrm{state}}=-\frac{1}{\ln \rho}
\]
with $\rho=\rho(DT_u(f_u^\ast))$ gives
\[
\tau_{\mathrm{state}}\le \frac{1}{\ln 2}.
\]
\end{theorem}

\begin{proposition}[Parameter-Family Persistence is not State Spectrum]
Let $F:\U\to\mathcal{B}$ be the fixed-point family $F(u)=f_u^\ast$. Any persistence of parameter labels or family coordinates belongs to the variation of $F$ over $\U$, not to the state-transition spectrum of $DT_u(f_u^\ast)$ for fixed $u$.
\end{proposition}

\begin{remark}[What has been removed]
The previous text incorrectly mixed strict contraction with a state-spectrum eigenvalue $\lambda=1$. BaseCore no longer does that. Any neutral or persistent mode must now be interpreted as a parameter-family bookkeeping mode, not as an eigenmode of the contractive state Jacobian.
\end{remark}

\begin{remark}[Identity neutrality]
In BaseCore, $\Id$ is a structural inverse-limit object only. It carries no automatic phenomenological, biological, or metaphysical interpretation.
\end{remark}

\begin{hypothesis}[Topological Regularity]\label{hyp:topo}
Each $S_t$ is compact Hausdorff and each $\pi_{t+1\to t}$ is continuous and surjective.
\end{hypothesis}

\begin{remark}[Persistent future branching as an operational form of NFD]
A sufficient operational strengthening of Hypothesis~\ref{hyp:nfd} is: for every $t$ there exists $k>t$ and $x_t\in S_t$ such that the fiber of $\pi_{k\to t}$ over $x_t$ contains at least two globally extendable compatible histories. BaseCore keeps the weaker NFD statement as the primary assumption because it is exactly what the non-locality theorem needs.
\end{remark}

\begin{remark}[What is \emph{not} proved here]
BaseCore does not prove that no arbitrary set-theoretic injection $\Id\to S_t$ can exist in every imaginable inverse system. It proves the narrower and correct claim that the canonical projective observations $p_t$ are not injective under Hypothesis~\ref{hyp:nfd}.
\end{remark}

\begin{proposition}[No Canonical Progressive Recovery under NFD]\label{thm:noprogressive}
Assume Hypothesis~\ref{hyp:nfd}. No finite canonical prefix map determines the inverse-limit identity object.
\end{proposition}

\begin{assumption}[RIG-1: Common Metric Stages]\label{ass:rig1}
Both towers use the same nonempty complete metric stages $(S_t,d_t)$ and continuous bonding maps. Use the weighted history metric below with $w_t\operatorname{diam}(S_t)\to0$. This fixes the ambient space used for both Hausdorff directions.
\end{assumption}

\begin{assumption}[RIG-2: Controlled Propagation]\label{ass:rig2}
For the fiber lifting constants $K_t>0$ of RIG-3 define $q_t=w_{t+1}K_t/w_t$. Require $C=\sup_{0\leq k\leq t<\infty}\prod_{j=k}^t q_j<\infty$. In particular $q_t\leq1$ at each stage suffices.
\end{assumption}

\begin{assumption}[RIG-3: Exact Fiber Lifts in Both Towers]\label{ass:rig3}
For each $f\in\{\pi_t,\widetilde\pi_t\}$, $u\in S_{t+1}$ and $v\in S_t$, there exists $u'\in S_{t+1}$ with $f(u')=v$ and $d_{t+1}(u,u')\leq K_t d_t(f(u),v)$. The same $K_t$ bounds both lifts. No continuous selection is required.
\end{assumption}

\begin{assumption}[RIG-4: Typed Projection Defects]\label{ass:rig4}
Write $\pi_t=\pi_{t+1\to t}$ and $\widetilde\pi_t=\widetilde\pi_{t+1\to t}$. Require $\sup_{u\in S_{t+1}} d_t(\pi_t(u),\widetilde\pi_t(u))\leq\epsilon_t<\infty$.
\end{assumption}

\begin{assumption}[RIG-5: Summable Deformation]\label{ass:rig5}
Require $E_w=\sum_{t\geq0}w_t\epsilon_t<\infty$.
\end{assumption}

\begin{definition}[Weighted Deformation Size]
The weighted deformation size is $\|\epsilon_\bullet\|_w=E_w$. When $\epsilon_t$ is the exact supremum projection defect this specifies a cost on the common-stage perturbations. An independently defined intervention cost needs its own quantitative relation to this sum.
\end{definition}

\begin{example}[Two Distinct Tail Failures]\label{ex:weighted-tail-failures}
On $S_t=[0,1]$ with identity bonding maps and $w_t=2^{-t}$, choose $d_t(s,u)=4^t|s-u|$. The two constant histories $0$ and $1$ have distance $+\infty$. For a different failure, take $S_t=\{0,1\}^t$ with prefix deletion and $d_t=2^t$ times the discrete metric. With the same weights every distinct pair of histories has distance $1$. The inverse limit has a compact product topology and a noncompact discrete metric topology. Flipping a bit at successively later levels gives product convergence to the unflipped history while all the weighted distances remain $1$.
\end{example}

\begin{theorem}[Conditional Stability of Inverse-Limit Identity]\label{thm:rigidity}
Under RIG-1 through RIG-5 the two limits $I=\Id$ and $\widetilde I=\widetilde{\Id}$ are nonempty. Every history in either limit has a compatible history in the other within distance $C E_w$. Thus $d_H(I,\widetilde I)\leq C E_w$.
\end{theorem}

\begin{corollary}[Conditional Isomorphism Requires Extra Structure]
The Hausdorff bound alone is a statement about the distance between sets. A homeomorphism follows under the commuting-bijection hypotheses below.
\end{corollary}

\begin{proposition}[Transport by Commuting Coordinate Bijections]\label{prop:coherent-history-transport}
Suppose the weighted metric induces the product topology and homeomorphisms $h_t:S_t\to S_t$ satisfy $\widetilde\pi_t h_{t+1}=h_t\pi_t$. Then $H(x)_t=h_t(x_t)$ maps the limits homeomorphically, with inverse $H^{-1}(y)_t=h_t^{-1}(y_t)$. Its displacement in the common history space is at most $\sup_t w_t\sup_{z\in S_t}d_t(z,h_t(z))$.
\end{proposition}

\begin{example}[Hausdorff Stability Without a Homeomorphism]\label{ex:hausdorff-not-isomorphism}
Take $S_t=\{0,\ldots,2^t-1\}$ with discrete distance scaled by $r>0$, $w_t=2^{-t}$, and $\pi_t(j)=\lfloor j/2\rfloor$. For $t\geq1$, change only the image of $j=1$ to $1$, keeping $\widetilde\pi_0=\pi_0$. Both maps remain surjective and satisfy the fiber estimate with $K_t=1$. The weighted intervention cost is $r\sum_{t\geq1}2^{-t}=r$. The all-zero history of the perturbed tower is isolated by the cylinder $y_1=0$ because each subsequent zero has exactly one lift. The original tower is the binary-prefix space and has no isolated histories. Thus the limits are not homeomorphic, even though the Hausdorff bound tends to zero with $r$. The perturbation hypotheses for the Hausdorff estimate all hold.
\end{example}

\begin{definition}[Ontological Mass]\label{def:ontmass}
Let $E_w(\delta)$ denote the weighted energy of an admissible perturbation family $\delta$. Define
\[
\MO:=\inf\left\{
\frac{E_w(\delta)}{d_H(\Id,\widetilde{\Id}_\delta)}
\;\middle|\;
\delta \text{ admissible},\ d_H(\Id,\widetilde{\Id}_\delta)>0
\right\},
\]
with the convention $\MO=+\infty$ if no admissible finite-energy perturbation yields positive deformation of the identity object.
\end{definition}

\begin{remark}[Interpretation discipline]
$\MO$ is a deformation-resistance scalar, not a metaphysical substance. BaseCore uses it only as a conditional invariant attached to admissible perturbation models.
\end{remark}

\begin{assumption}[NS-1: Target and Observable Family]\label{ass:ns1}
Fix a nonempty set of compatible histories $X\subseteq\Id$, a family of queries $J$, and responses $F_j:X\to (Y_j,\rho_j)$. The query can specify an observable, a time horizon, or a declared intervention. All queries refer to the same encoded history. The intervention protocol and parameters are known to both parties and fixed independently of the history, except for information explicitly included in the encoded state. Non-finite determination and deformation resistance are separate properties of a target, measured using their own definitions.
\end{assumption}

\begin{assumption}[NS-2: Binary Representation Budget]\label{ass:ns2}
A deterministic encoder $c:X\to\{0,1\}^B$ has at most $2^B$ possible representations. The budget includes all history-dependent information accessible to the decoder. An adaptive binary transcript of depth at most $B$ satisfies the same bound when its query tree is fixed in advance and the choices and termination are determined by its previous bits. An exact real parameter is outside this finite-alphabet class.
\end{assumption}

\begin{assumption}[NS-3: Uniform Response Fidelity]\label{ass:ns3}
The decoders $g_j:\{0,1\}^B\to Y_j$ must satisfy $\rho_j(g_j(c(x)),F_j(x))\leq\eta$ for every $x\in X$ and $j\in J$. The tolerance is in the declared response units, after normalizing them if necessary. Faithfulness of additional structures, such as the bonding maps or the intervention cost sector, imposes separate constraints.
\end{assumption}

\begin{theorem}[Finite-Budget Obstruction by Response Separation]\label{thm:non-simulability}
Under NS-1--NS-3, let $A\subseteq X$ be a finite set such that for each distinct $x,y\in A$ there is $j$ with $\rho_j(F_j(x),F_j(y))>2\eta$. Then $|A|\leq 2^B$. For exact fidelity, a code exists exactly when the number of equivalence classes of $x\sim y$ defined by $F_j(x)=F_j(y)$ for all $j$ is at most $2^B$.
\end{theorem}

\begin{theorem}[Approximation Barrier]\label{thm:finite-budget-approximation}
On the binary prefix tower $S_t=\{0,1\}^{t}$ with weights $w_t=2^{-t}$ and discrete stage metrics, use $Y=X=\{0,1\}^{\mathbb N}$ as the decoded history space, with $d_w(x,y)=2^{-m}$ at the first differing bit $m\geq1$. Among all encoders with at most $2^B$ states and decoders into $X$, the minimum worst-case $d_w$ error is $2^{-(B+1)}$. Exact recovery of all finite prefix responses requires unbounded $B$ as the query horizon increases.
\end{theorem}

\begin{example}[One Exact Real Encodes Every Binary History]\label{ex:unbounded-precision-control}
The map $b\mapsto\sum_{j\geq1}2b_j3^{-j}$ is injective: at the first unequal bit $j$ the leading difference is $2\cdot3^{-j}$ and the remaining tail is bounded by $3^{-j}$. On the image, inverse decoding followed by each prefix projection recovers all the canonical observations from one exact real. As a separate intervention control, any declared family that leaves the target limit set fixed has $\MO=+\infty$ by the defining convention, even if the allowed interventions have finite cost. Neither fact supplies a finite binary budget.
\end{example}

\begin{remark}[What has been removed]
The resource obstruction concerns the declared responses, metric tolerance and binary budget. Infinite-precision scalar encodings and finite-cost interventions require independent hypotheses before a binary-budget theorem can be applied to them. In the CCR program, non-finite determination and infinite resistance are separately specified; any stronger obstruction to faithful embeddings must state its category and preserved observations. Exact response classes determine whether a finite sufficient statistic exists for the declared queries.
\end{remark}

\begin{definition}[Phenomenological Space]\label{def:phenspace}
A phenomenological space is a nonempty set $\mathcal{E}$ whose elements are called \textit{phenomenological configurations}. No topology, metric, or algebraic structure is assumed a priori.
\end{definition}

\begin{remark}
We do not claim that $\mathcal{E}$ represents ``conscious states'' or ``qualia''. It is an abstract mathematical space whose interpretation is not specified by the formalism. The space $\mathcal{E}$ is introduced purely as the codomain of a structural assignment; its ontological status is deliberately left open.
\end{remark}

\begin{proposition}[Endomorphisms Preserving All Canonical Projections]
If $F:\mathcal I\to\mathcal I$ satisfies $p_t\circ F=p_t$ for every $t$, then $F=\operatorname{Id}$. This does not exclude endomorphisms with nonidentity coordinate actions.
\end{proposition}

\begin{definition}[Phenomenological Assignment]\label{def:phenassign}
A phenomenological assignment is a family of total maps on the declared observable state spaces:
\begin{equation}
    \phi_t: S_t \to \mathcal{E}
\end{equation}
indexed by $t \in \mathbb{N}$.
\end{definition}

\begin{definition}[Induced Limit Assignment]\label{def:limitassign}
Given a phenomenological assignment $\{\phi_t\}$, the induced limit assignment, whenever it exists, is the map:
\begin{equation}
    \Phi: \mathcal{I} \to \mathcal{E}, \quad \Phi((x_t)_t) := \lim_{t \to \infty} \phi_t(x_t),
\end{equation}
The convergence statements below use the complete metric codomain of Hypothesis~\ref{hyp:H3-metric}. Partial readouts may instead be studied on a specified common domain, with all projections and factorizations restricted to that domain.
\end{definition}

\begin{axiom}[E0: Non-Triviality]\label{ax:e0}
The phenomenological space satisfies $|\mathcal{E}| \geq 2$, i.e., there exist at least two distinct phenomenological configurations.
\end{axiom}

\begin{axiom}[E2: Non-Locality]\label{ax:e2}
There exists no function $f: S_t \to \mathcal{E}$ (for any fixed $t$) such that for all trajectories $(x_t)_t \in \mathcal{I}$:
\begin{equation}
    \Phi((x_t)_t) = f(x_t).
\end{equation}
\end{axiom}

\begin{theorem}[E0 is Necessary]\label{thm:e0-necessary}
If $|\mathcal{E}| = 1$, then every phenomenological assignment is constant and no phenomenological classification is possible.
\end{theorem}

\begin{theorem}[Controlled Compatibility Is Sufficient]\label{thm:e1-necessary}
E1 guarantees existence of the limit with the error bound in Proposition~\ref{prop:unique-phi}. Absolute summability is sufficient, not necessary for an arbitrary convergent family.
\end{theorem}

\begin{theorem}[Non-Factorization Is an Independent Requirement]\label{thm:e2-necessary}
E2 excludes readouts determined by a single canonical finite cut. The inverse-limit construction and E1 alone do not imply E2.
\end{theorem}

\begin{theorem}[Logical Dependencies of the Assignment Conditions]\label{thm:minimality}
On a nonempty trajectory domain, E2 implies E0. E1 does not imply E2. There exist assignments satisfying E0, the revised E1 and E2 simultaneously. Consequently these three conditions are not an independent minimal axiom basis as originally stated.
\end{theorem}

\begin{proposition}[Exact Compatibility Forces Finite-Cut Factorization]\label{prop:exact-e1-obstruction}
On a nonempty trajectory domain, if $\phi_{t+1}(p_{t+1}x)=\phi_t(p_tx)$ for every $x,t$, then the limit assignment satisfies $\Phi=\phi_0\circ p_0$. It cannot satisfy E2. The controlled E1 above replaces that exact equality, rather than assuming it together with E2.
\end{proposition}

\begin{proposition}[Sharp Error for Arbitrary Binary Codes]\label{prop:ternary-arbitrary-code}
For the ternary assignment above, let an encoder choose at most $2^B$ states as an arbitrary function of the whole history, and let each state decode to any real number. The minimum worst-case absolute error is $1/(2\cdot3^B)$ for every integer $B\geq0$.
\end{proposition}

\begin{proposition}[Setwise Invariance Does Not Supply Continuity]\label{prop:readout-continuity-control}
Controlled E1 and E2 can hold for a discontinuous assignment, even if the identity domain is fixed under every declared intervention.
\end{proposition}

\begin{proposition}[Setwise and Pointwise Transport Are Distinct]\label{prop:transport-control}
Preserving an identity domain as a set does not guarantee equal values of a common readout on transported states.
\end{proposition}

\begin{definition}[Phenomenological Compatibility Class]\label{def:compat-class}
For a declared identity domain and codomain, $\mathcal P(M_\Omega)$ consists of maps $\Phi:\mathcal I\to\mathcal E$ that are limits of some family $\{\phi_t\}$ satisfying E1, with E0 and E2 also satisfied. The readout family and its tail control are part of the realization data. The notation retains the mass index for comparisons, but no mass-dependent restriction follows from E0--E2 alone.
\end{definition}

\begin{remark}
The compatibility class records choices of domain, codomain and readout family. A numerical mass label does not by itself determine those choices or their transport under perturbations.
\end{remark}

\begin{hypothesis}[H3: Metric on $\mathcal{E}$]\label{hyp:H3-metric}
The phenomenological space $\mathcal{E}$ admits a metric $d_\mathcal{E}$ such that $(\mathcal{E}, d_\mathcal{E})$ is a complete metric space.
\end{hypothesis}

\begin{theorem}[Metric Data Required by Quantitative Formulas]\label{thm:h3-necessary}
The distance-based fragmentation and loss functionals used here require a declared metric, or a pseudometric with a stated quotient convention. Topological continuity can be defined without a metric. Completeness is used for the Cauchy-limit guarantee of E1.
\end{theorem}

\begin{proposition}[Completeness and Existence of Limits]\label{prop:complete-necessary}
Without completeness, the conclusion that every E1-type Cauchy family has its limit in the declared codomain can fail. Completeness is not necessary for a family whose limit is already known to belong to that codomain.
\end{proposition}

\begin{definition}[Phenomenological Continuity]\label{def:phen-continuity}
A phenomenological assignment $\Phi: \mathcal{I} \to \mathcal{E}$ is \textit{structurally continuous} if for every sequence $(x^{(n)})_n$ in $\mathcal{I}$ converging in the $d_w$ metric:
\begin{equation}
    d_w(x^{(n)}, x) \to 0 \implies d_\mathcal{E}(\Phi(x^{(n)}), \Phi(x)) \to 0.
\end{equation}
\end{definition}

\begin{remark}
Structural continuity is derived under the finite-readout conditions of Theorem~\ref{thm:forced-continuity}. It is distinct from invariance under an external intervention.
\end{remark}

\begin{definition}[Phenomenological Fragmentation]\label{def:fragmentation}
A phenomenological assignment $\Phi$ is \textit{fragmentable} if there exists a perturbation $\{\epsilon_t\}$ with finite weighted energy such that:
\begin{equation}
    d_\mathcal{E}(\Phi(x), \tilde{\Phi}(\tilde{x})) > 0
\end{equation}
for corresponding identity trajectories $x \in \mathcal{I}$ and $\tilde{x} \in \tilde{\mathcal{I}}$.
\end{definition}

\begin{remark}
Fragmentation captures the vulnerability of phenomenological structure to perturbations. It is the phenomenological analog of identity deformability.
\end{remark}

\begin{hypothesis}[$\Phi$-Regularity Lower Bound]\label{hyp:phi-regularity}
Let $(\mathcal{I}, d_w)$ be the identitary metric space from \textit{Rigid Identity} and let $(\mathcal{E}, d_\mathcal{E})$ be the abstract phenomenological metric space. A phenomenological assignment $\Phi: \mathcal{I} \to \mathcal{E}$ is said to satisfy $\Phi$-regularity when it satisfies:
\begin{enumerate}[leftmargin=*]
    \item (Properness) For every compact $K \subset \mathcal{E}$, $\Phi^{-1}(K)$ is compact in $\mathcal{I}$.
    \item (Local Lipschitz regularity) For every $x \in \mathcal{I}$, there exist $\varepsilon > 0$ and $L_x > 0$ such that for all $y, z \in B_\varepsilon(x)$:
    \begin{equation}
        d_\mathcal{E}(\Phi(y), \Phi(z)) \leq L_x \cdot d_w(y, z).
    \end{equation}
    \item (Non-collapse) For every $x \in \mathcal{I}$ and every $r > 0$, the restriction of $\Phi$ to $B_r(x)$ is not constant.
    \item (Global lower Lipschitz bound) There exists a constant $C>0$ such that for all $x,y\in\mathcal{I}$,
    \begin{equation}
        d_\mathcal{E}(\Phi(x),\Phi(y)) \geq C\cdot d_w(x,y).
    \end{equation}
\end{enumerate}
\end{hypothesis}

\begin{caveat}[Status of $\Phi$-regularity]
The fourth clause is an additional structural assumption, not a consequence of the first three clauses. The counterexample in Appendix~\ref{app:phi-regularity-counterexample} shows that properness, local Lipschitz regularity, and non-collapse do not imply any uniform lower Lipschitz constant.
\end{caveat}

\begin{hypothesis}[Audited Perturbation Comparisons]\label{hyp:audited-comparison}
Declare a finite-cost intervention class $\mathcal V$, a common metric space $(Z,d_Z)$ containing the unperturbed and perturbed identity domains, and transports $h_\varepsilon:\mathcal I\to\mathcal I_\varepsilon\subseteq Z$. Readouts are restrictions of one declared map $F:Z\to\mathcal E$: $\Phi=F|_{\mathcal I}$ and $\Phi_\varepsilon=F|_{\mathcal I_\varepsilon}$.
The following branches are alternatives, used separately. The positive-displacement branch has some $\varepsilon\in\mathcal V$ and $x\in\mathcal I$ with $d_Z(x,h_\varepsilon x)>0$. The zero-displacement branch has $h_\varepsilon x=x$ for every $\varepsilon\in\mathcal V$ and $x\in\mathcal I$. Any use of the lower Lipschitz bound in a comparison requires that bound for $F$ on the common comparison domain, not merely within one identity object.
\end{hypothesis}

\begin{remark}[Burden linking rigidity and readout comparisons]
The scalar $M_\Omega$ does not itself supply the transports or a common readout. Relating its finite and infinite regimes to these two branches is a separate model obligation. Setwise invariance does not imply pointwise fixed transport, and a lower bound within one domain does not compare unrelated assignments on different domains.
\end{remark}

\begin{corollary}[Fragmentability and Continuity Are Distinct]
The positive-displacement conclusion does not establish a topological discontinuity. A continuous assignment may be fragmentable under a state-changing intervention.
\end{corollary}

\begin{corollary}[Invariance on the Audited Zero-Displacement Branch]
A CCR model satisfying the zero-displacement comparison hypothesis has invariant assignment values under all interventions in its declared finite-cost class.
\end{corollary}

\begin{theorem}[Conditional Classification by Audited Branches]\label{thm:dichotomy}
Suppose a model supplies the positive-displacement branch and lower bound whenever $M_\Omega<\infty$, and supplies continuous finite readouts and the zero-displacement branch whenever $M_\Omega=+\infty$. Then its finite regime is fragmentable and its infinite regime has a continuous, perturbation-invariant assignment. The mass cases are exclusive; fragmentability and topological continuity need not be exclusive properties.
\end{theorem}

\begin{proposition}[The Mass Label Does Not Define Assignment Existence]
For fixed identity domain, codomain and readout family, the class defined by E0--E2 is independent of a numerical label $M_\Omega$. A claim that $M_\Omega=0$ excludes assignments needs an additional link to the domain or admissible readouts.
\end{proposition}

\begin{proposition}[Deformable Branch with Comparison Data]
For $0<M_\Omega<\infty$, the positive-displacement and lower-bound hypotheses of Theorem~\ref{thm:fragmentation} imply fragmentability.
\end{proposition}

\begin{proposition}[Rigid Branch with Comparison Data]
For $M_\Omega=+\infty$, continuous finite readouts under E1 imply continuity, and the zero-displacement branch implies perturbation invariance. These are the respective hypotheses of Theorem~\ref{thm:forced-continuity}.
\end{proposition}

\begin{lemma}[Inheritance under Audited Fixed Transport]
An assignment satisfying the zero-displacement comparison branch inherits invariance under that declared intervention class. This applies to CCR realizations only after checking that branch.
\end{lemma}

\begin{definition}[Phenomenological Attractor Set]\label{def:phenomenological-attractor}
Use $\Attr(S)$ for structurally stable readout values under a declared perturbation/extension family, as defined below. Temporal attraction would additionally require a dynamics and a basin; neither is implied by this notation.
\end{definition}

\begin{definition}[Phenomenological Stability]\label{def:phenomenological-stability}
A value $e=\Phi_S(z)$ is structurally stable if a finite modulus $\omega(\rho)\to0$ as $\rho\downarrow0$ controls $\dE(\Phi_{S'}(Pz),e)\leq\omega(\rho)$ for all declared perturbation transports $P$ of cost at most $\rho$. Exact persistence instead requires equality. Stability does not force equality at a nonzero perturbation budget.
\end{definition}

\begin{lemma}[Bridge Lemma]\label{lem:null-bridge}
For any defined $e\in\E$, distance $\dE(e,\nullphi)=0$ implies $e=\nullphi$. No CCR assumption is needed.
\end{lemma}

\begin{corollary}[Conditional Forced Non-Nullity]\label{cor:forced-non-nullity}
Under the separated-pair hypotheses, at least one witness image is non-null. If one endpoint is fixed at null, the other has null distance at least $C\epsilon$. CCR alone does not select a non-null endpoint or guarantee a stable regime.
\end{corollary}

 egin{definition}[Positive Regime Space]\label{def:positive-regime-space}
Let $\Eplus=\E\setminus\{
ullphi\}$ with inherited order. For a witness pair, let $A=\{\Phi(z_0),\Phi(z_1)\}\setminus\{
ullphi\}$ and $A_0=A\cup\{
ullphi\}$.
\end{definition}

\begin{theorem}[Minimal Positive Witness Regime]\label{thm:minimal-positive-regime}
The finite positive witness image $A$ is non-empty and has a minimal element. If its two possible values are comparable, it has a unique least element. No ambient order completeness is needed. This does not prove a least member of all of $\Eplus$.
\end{theorem}

\begin{definition}[Structural Intensity]\label{def:structural-intensity}
Distinguish null distance $r(e)=\dE(e,\nullphi)$, global lower gap $\iota(e)=\inf_{f\in\E,\ f\prec e}\dE(e,f)$, and the audited relative gap $\iota_{A_0}(e)$ obtained by restricting this infimum to $f\in A_0$. All are measured in units of $\dE$. A positive null distance does not imply a positive global gap.
\end{definition}

\begin{theorem}[Anchored Witness Intensity Bound]\label{thm:universal-intensity-bound}
If one endpoint is null, the other image $e$ is the unique positive member of $A$ and satisfies $\iota_{A_0}(e)=r(e)\geq C\epsilon>0$. Without that anchor, only $\max_i r(\Phi(z_i))\geq C\epsilon/2$ follows. No universal global intensity bound is claimed.
\end{theorem}

\begin{theorem}[Conditional Phenomenological Closure]\label{thm:forced-phenomenological-closure}
A declared detected pair gives joint null exclusion and a minimal positive member of its finite image. A null anchor gives a unique positive witness value and the anchored quantitative bound. Uniqueness in the ambient regime space, temporal stability and CCR realizability require further hypotheses and constructions.
\end{theorem}

\begin{proposition}[Profinite Bound]\label{prop:profinite-bound}
A profinite witness pair with declared positive separation $\epsilon$, certified lower constant $C_{\mathrm{prof}}>0$ and one null endpoint gives $r(e)\geq C_{\mathrm{prof}}\epsilon$. Summable coordinate costs do not by themselves certify CCR.
\end{proposition}

\begin{proposition}[Symbolic Bound]\label{prop:symbolic-bound}
The same anchored conclusion holds for a symbolic witness with its audited metric and lower constant. The full binary shift with complement intervention and summable coordinate-change costs is a control against automatic infinite mass.
\end{proposition}

\begin{theorem}[Rigidity Inheritance]\label{thm:rigidity-inheritance}
For $\Phi'=b\circ\Phi\circ a$, lower constants $c_a$ for $a$, $C$ for $\Phi$ on the mapped pairs and $c_b$ for $b$ give lower constant $c_ac_bC$. CCR inheritance separately requires every new finite-cost positive deformation to pull back to one in the old sector. Summability alone proves neither statement.
\end{theorem}

\begin{theorem}[Factorization on a Faithful Image]\label{thm:null-categorical-universality}
If $\Phi:Z\to\E$ has a positive global lower bound, then every map $\Psi:Z\to F$ factors uniquely through $\Phi(Z)$. If $\Psi$ is $L$-Lipschitz, the factor is $L/C$-Lipschitz. No unique extension to the whole ambient $\E$ is implied.
\end{theorem}

\begin{theorem}[Finite-Prefix Simulation Bound]\label{thm:null-simulation-lower-bound}
For $F(b)=\sum_{j\geq0}2b_j/3^{j+1}$ and a decoder observing only bits $0,\ldots,N$, the optimal worst-case scalar error is $1/(2\,3^{N+1})$. It is positive for every fixed prefix and tends to zero with growing budget. The conclusion concerns prefix information, not finite real dimension.
\end{theorem}

\begin{theorem}[Conditional Closure by Non-Alternatives]\label{thm:null-closure-by-non-alternatives}
Any alternative model satisfying the same declared pair, lower-bound, anchor and transport hypotheses obeys the corresponding preceding conclusions. The program of realizing these properties jointly with an infinite-mass intervention model remains open; pair separation is not a proof of an individual null state's dynamical instability.
\end{theorem}

\begin{definition}[BaseCore Envelope]
The BaseCore envelope is the collection of theorem-level structures owned directly by this source tree:
\begin{enumerate}[leftmargin=*]
\item foundational Hilbert-space projection dynamics;
\item typed computable witnesses and state spectral-gap bounds;
\item parameterwise non-collapse under explicit anti-constant assumptions;
\item inverse-limit identity under non-finite-determination assumptions;
\item conditional rigidity under admissible perturbation models;
\item conditional obstruction to uniform response fidelity under a binary representation budget;
\item operational-criterion grammar, certification, falsation, and claim-boundary ledgers.
\end{enumerate}
\end{definition}

\begin{proposition}[Boundary Discipline]
BaseCore may define structures that downstream layers use, but it does not claim downstream closure. In particular, BaseCore does not by itself own runtime thresholds, bridge admissibility, human-comparator programs, phenomenality burdens, or Papers 7--9.
\end{proposition}

\begin{remark}[Why the earlier material was removed from BaseCore ownership]
Previous versions mixed theorem-tight base results with runtime-like numerics, non-convex extension classes, and bridge-facing vocabulary. That blurred the mathematical base layer. BaseCore now keeps only the theorem ownership that survives the stricter release gate.
\end{remark}

\begin{definition}[Downstream admissible extension]
A downstream layer is an admissible extension of a BaseCore export object $\mathfrak{E}$ only if it supplies:
\begin{enumerate}[leftmargin=*]
\item an explicit target predicate $P$ not already contained in $\mathcal{R}$;
\item a typed construction or estimator witnessing the objects on which $P$ is evaluated;
\item a proof, reduction, or reproducible protocol connecting $\mathcal{H}$ to $P$;
\item negative controls or failure modes under which $P$ must not be asserted;
\item a provenance statement distinguishing theorem, implementation, internal support, and external adjudication.
\end{enumerate}
\end{definition}

\begin{proposition}[No automatic downstream promotion]
Let $\mathfrak{E}=(\mathcal{O},\mathcal{H},\mathcal{R},\mathcal{B})$ be a BaseCore export object and let $P$ be a predicate introduced outside BaseCore. If $P\notin\mathcal{R}$, then BaseCore does not entail $P$ unless an admissible extension supplies an additional bridge from $\mathcal{H}$ to $P$.
\end{proposition}

\begin{criterion}[Runtime-use admissibility]
A runtime measurement may instantiate a BaseCore export object only as an implementation-level witness when all of the following are recorded: the measured state space, the estimator or update rule, the finite horizon, the calibration regime, the controls under which the measurement fails, and the claim class being asserted. Such a measurement is not a BaseCore theorem and is not external validation by itself.
\end{criterion}

\begin{remark}[Open-load placement for $I_{\mathrm{int}}$ and atomic separators]
Quantities such as $I_{\mathrm{int}}$ and any atomic-separator condition may be treated as downstream target predicates or estimator families only after their carrier objects, separator class, invariance target, and negative controls are specified. Until a proof or reproducible adversarial protocol closes that burden, BaseCore may export the ambient structural language but not the separator conclusion.
\end{remark}

\begin{proposition}[Boundary preservation under finite implementations]
Suppose a finite implementation produces diagnostics for a downstream predicate $P$ over a bounded horizon. If the implementation does not prove that the diagnostics are invariant over the relevant mathematical class, then the diagnostics remain implementation evidence for $P$ and do not promote $P$ to a BaseCore result.
\end{proposition}

\begin{definition}[Admissible system]\label{def:system}
An admissible system is a tuple
\[
S=(X,\Phi,C,R,\Gamma,U)
\]
where:
\begin{enumerate}[leftmargin=1.5em]
\item $X$ is a metrizable internal state space with metric $d_X$;
\item $\Phi=\{\Phi_u\}_{u\in U}$ is a family of admissible transition operators $\Phi_u:X\to X$;
\item $C$ is the effective causal structure used to test admissible factorization and intervention behavior;
\item $R=\{r_\alpha\}_{\alpha\in\Lambda_R}$ is a family of readouts, each $r_\alpha:X\to Y_\alpha$;
\item $\Gamma=\{\gamma_j\}_{j=1}^m$ is an admissibility bundle defining
\[
X_\Gamma=\{x\in X:\gamma_j(x)\le 0\ \forall j\};
\]
\item $U$ is the set of admissible interventions.
\end{enumerate}
\end{definition}

\begin{definition}[Admissible support]\label{def:support}
A subset $\Aset\subseteq X_\Gamma$ is an admissible support if:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is non-empty and compact;
\item $\Phi_u(\Aset)\subseteq \Aset$ for every $u\in U$;
\item $\Aset\cap \operatorname{Attr}_X(S)\neq\varnothing$;
\item $\Aset$ stays disjoint from the collapse set excluded by the base non-collapse burden.
\end{enumerate}
\end{definition}

\begin{definition}[Operational partition candidate]\label{def:partition}
An operational partition candidate is a map
\[
\pi_{S,T}:\Hist_{S,T}\to \Class_{S,T}
\]
into a finite or countable label set $\Class_{S,T}$.
\end{definition}

\begin{definition}[Structural persistence]\label{def:iper}
An admissible system satisfies structural persistence, written $\Iper(S)=1$, if there exists an admissible support $\Aset$ and a constant $\delta_{\mathrm{per}}(S)>0$ such that:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is forward invariant under all $u\in U$;
\item every admissible trajectory starting in $\Aset$ remains at least $\delta_{\mathrm{per}}(S)$ away from the collapse set;
\item $\Aset$ contains or converges into a non-empty admissible attractor region.
\end{enumerate}
\end{definition}

\begin{definition}[Rigid identity]\label{def:iri}
An admissible system satisfies rigid identity, written $\Iri(S)=1$, if the observable family induced by $R$ on $\Aset$ determines a unique identity object $\Id_S$ and there exists a gap $\delta_{\mathrm{ri}}(S)>0$ such that every admissible alternative identity candidate remains at weighted deformation distance at least $\delta_{\mathrm{ri}}(S)$ from $\Id_S$.
\end{definition}

\begin{lemma}[Two Factor Fibers Cannot Share a Nonconstant Label]\label{lem:two-factor-label-obstruction}
Let $\chi:A\to A_1\times A_2$ be surjective. If a label $g:A\to L$ is constant on every fiber of each of the two factor projections of $\chi$, then $g$ is constant on $A$.
\end{lemma}

\begin{definition}[Regime continuity]\label{def:icont}
An admissible system satisfies regime continuity, written $\Icont(S)=1$, if there exists a complete metric space $(\E,d_\E)$ and an admissible assignment
\[
\Pi_S:\Aset\to \E
\]
such that:
\begin{enumerate}[leftmargin=1.5em]
\item every admissible trajectory induces a continuous path in $\E$ on admissible windows;
\item there exists $\delta_{\mathrm{cont}}(S)>0$ bounding the fragmentation functional on all admissible histories;
\item no admissible finite-energy perturbation produces a discontinuous jump into an incompatible regime class while $\Id_S$ is preserved.
\end{enumerate}
\end{definition}

\begin{definition}[Decoder Family and Structural Closure]\label{def:decoder}
A decoder family uses one declared class set and acts on the specified history windows. For each intervention-response comparison, declare its response cells and a matching relation on those cells. The family is structurally closed when decoder class equality composes exactly and the response-cell matching relations are reflexive, symmetric and transitive. These are conditions on the chosen comparison data; they are not inferred from a numerical tolerance alone. The legibility clauses below supply the additional operational requirements.
\end{definition}

\begin{definition}[Operational legibility]\label{def:ileg}
An admissible system satisfies operational legibility, written $\Ileg(S)=1$, if there exist:
\begin{enumerate}[leftmargin=1.5em]
\item a declared readout subfamily $\Read^{\mathrm{leg}}\subseteq R$;
\item a structurally closed decoder family $\Dec_S$ acting on windows of length at least $\tau_{\min}(S)$;
\item a class set $\Class_S$;
\item a measurement protocol with separation $\sigma>0$, readout noise radius $r>0$, minimum duration $\tau_{\min}\ge1$, miss and false-positive budgets $p_{\mathrm{miss}},p_{\mathrm{fp}}\in[0,1)$, and a finite compression budget $B$ with class-distortion tolerance $d_{\mathrm{comp}}$;
\end{enumerate}
such that:
\begin{description}[leftmargin=1.7em]
\item[(L1) Separability] Distinct declared classes have distance at least $\sigma$ in the specified clean comparison domain.
\item[(L2) Noise robustness] On the specified noise domain, perturbations with readout norm at most $r$ preserve the label.
\item[(L3) Persistence window] Under declared sham schedules, labels remain stable throughout every tested window of duration $\tau_{\min}$.
\item[(L4) Intervention fidelity] In a declared nonempty target population, the miss probability for a predicted class shift is at most $p_{\mathrm{miss}}$.
\item[(L5) Negative controls] In a declared nonempty sham population, the false-shift probability is at most $p_{\mathrm{fp}}$.
\item[(L6) Structured compressibility] An encoder with at most $2^B$ codes and a code-to-class map preserve nontrivial class structure with distortion at most $d_{\mathrm{comp}}$ in the declared class metric.
\end{description}
\end{definition}

\begin{proposition}[Each invariant is individually necessary]\label{prop:invariant-necessity}
If any one of $\Iper,\Iri,\Iint,\Icont,\Idiff,\Ileg$ fails, then $S\notin\Critop$.
\end{proposition}

\begin{definition}[Certified decoder]
A decoder $D\in\Dec_S$ is certified as part of a structurally closed family when the six clauses of Definition~\ref{def:ileg} hold on the chosen admissible support. Structural closure and operational certification are separate requirements.
\end{definition}

\begin{proposition}[Well-definedness of the certified partition]\label{prop:qop-welldefined}
On any declared support $\Aset$ with a structurally closed decoder family, the relation $\sim_{\Partop,S}$ is an equivalence relation. This conclusion does not require the other critical invariants; certification of criterion membership still does.
\end{proposition}

\begin{remark}[Tolerance Alone Is Not Transitive]\label{rem:tolerance-control}
With constant decoder labels, let response matching mean distance at most $1$ on $\{0,3/4,3/2\}$. Adjacent points match, but the endpoints do not. Thus decoder equality plus raw tolerance is not enough. By contrast, equality under a declared response-cell map is an equivalence relation and supplies a concrete structurally closed matching rule. This example concerns closure only, not satisfaction of all six legibility clauses.
\end{remark}

\begin{definition}[Certified operational partition]\label{def:qop}
Assume Proposition~\ref{prop:qop-welldefined}. The certified operational partition of $S$ is
\[
\Partop(S):=\Aset/{\sim_{\Partop,S}}.
\]
\end{definition}

\begin{definition}[Operational-criterion class membership]\label{def:cop}
An admissible system belongs to the BaseCore operational-criterion class, written $S\in\Critop$, if there exists a non-empty admissible support $\Aset$ such that
\[
\Iper(S)=\Iri(S)=\Iint(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1.
\]
\end{definition}

\begin{remark}[Neutrality of the class symbol]
The symbol $\Critop$ is a shorthand for a conjunctive operational criterion. It is not a theorem of phenomenality, metaphysical subjectivity, or human equivalence.
\end{remark}

\begin{definition}[Rupture]\label{def:rupture}
A rupture is any loss of admissibility or loss of at least one critical invariant margin beyond its admissible threshold.
\end{definition}

\begin{theorem}[Rupture by Invariant Loss]\label{thm:rupture}
If a critical invariant has no admissible witness on any support, then $S\notin\Critop$. Loss of a witness on one chosen support invalidates that support's certificate, but does not exclude a certificate on another support without further analysis. Quotient undefinedness, triviality and loss of legibility are not mutually exclusive labels and need not accompany every loss of criterion membership.
\end{theorem}

\begin{definition}[Single-rupture witness family]
Fix one invariant index $k\in\{\mathrm{per},\mathrm{ri},\mathrm{int},\mathrm{cont},\mathrm{diff},\mathrm{leg}\}$. A single-rupture witness family $\mathcal{W}_k$ consists of admissible systems for which predicate $I_k$ fails and every other predicate holds on the declared comparison domain.
\end{definition}

\begin{theorem}[Minimality of the six-invariant basis]\label{thm:invariant-basis-minimality}
Let $\mathfrak{U}$ be any admissible universe containing at least one single-rupture witness for each invariant. Then no strict subset of $\mathfrak{I}$ is extensionally equivalent to $\Critop$ on $\mathfrak{U}$.
\end{theorem}

\begin{criterion}[Legibility certificate]\label{crit:legibility}
An operational partition candidate is certified only if:
\begin{enumerate}[leftmargin=1.5em]
\item comparator separability holds against pre-registered baselines;
\item admissible noise does not dissolve the class map below the legibility margin;
\item the same class assignment survives on windows of length at least $\tau_{\min}(S)$;
\item targeted interventions on an invariant induce the predicted directional class change;
\item sham or off-target interventions do not generate the same class signature;
\item audit-friendly compression preserves class structure without total collapse.
\end{enumerate}
\end{criterion}

\begin{proposition}[Legibility is jointly constrained]\label{prop:legibility}
No single legibility metric is sufficient for $\Ileg$. The invariant requires simultaneous control of separation, admissible noise robustness, persistence window, intervention fidelity, negative controls, and structured compressibility.
\end{proposition}

\begin{definition}[Base criterion certificate]\label{def:cert}
A BaseCore criterion certificate for an admissible system $S$ is a tuple
\[
\Cert(S)=\bigl(\Aset,\Dec_S,\pi_S,\Delta(S),E_S\bigr),
\]
where:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is a certified admissible support;
\item $\Dec_S$ is a certified decoder family;
\item $\pi_S$ is the decoder-induced partition on admissible histories;
\item $\Delta(S)$ is the witness margin vector;
\item $E_S$ is the evidence bundle localizing the witness for each invariant.
\end{enumerate}
\end{definition}

\begin{criterion}[Candidate certification rule]\label{crit:cert}
A candidate system may be certified as a member of $\Critop$ only if all of the following are available on the same admissible support:
\begin{enumerate}[leftmargin=1.5em]
\item a non-empty compact forward-invariant support certificate;
\item a positive witness margin vector $\Delta(S)>0$ coordinate-wise;
\item a decoder family satisfying Definition~\ref{def:ileg};
\item a targeted intervention panel together with negative controls;
\item an auditable compression map preserving class structure;
\item a traceable dependency ledger showing which upstream result supports each invariant witness.
\end{enumerate}
\end{criterion}

\begin{theorem}[Certified criterion membership]
If $\Cert(S)$ exists and satisfies Criterion~\ref{crit:cert}, then $S\in\Critop$ and $\Partop(S)$ is well-defined.
\end{theorem}

\begin{remark}[Boundary discipline]
The section above defines a theorem-tight grammar for certification, rupture, and falsation. It does not prove phenomenality, subjectivity, biological primacy, or cross-substrate identity transport.
\end{remark}

\begin{definition}[Forensic packet]\label{def:forensic-packet}
Each operational run emits a packet
\[
K=(\mathrm{tick},\mathrm{seed},\mathrm{versionHash},H_v,\mathrm{metrics},\mathrm{sensorSummary},\mathrm{checksum}).
\]
\end{definition}

\begin{assumption}[Packet admissibility]\label{ass:packet-admissibility}
A run is admissible only if checksum, schema, seed consistency, version hash, and $H_v$ consistency all pass.
\end{assumption}

\begin{definition}[Severe violation]\label{def:severe-violation}
A run has a severe violation if any of the following holds: checksum mismatch, schema failure, seed/version inconsistency, or critical-state replay mismatch.
\end{definition}

\begin{criterion}[Integrity gate]\label{crit:integrity-gate}
Severely violated runs are excluded from support counting and marked as hard failures.
\end{criterion}

\begin{proposition}[Integrity-first inference]\label{prop:integrity-first}
If admissibility fails, inferential significance is non-actionable.
\end{proposition}

\begin{definition}[Operational Certification Indicator]\label{def:operational-certification}
Keep $\Cert(S)$ for the certificate object of Definition~\ref{def:cert}. Define a distinct mathematical indicator $\operatorname{CertFlag}(S)$ to be $1$ exactly when such a certificate satisfies Criterion~\ref{crit:cert} on one common admissible support and meets the integrity grammar above; otherwise its value is $0$. This does not identify a tuple with a Boolean value. An empirical audit may have an unknown verdict: missing evidence is not a proof that this mathematical indicator is zero.
\end{definition}

\begin{proposition}[Ablation prediction]\label{prop:ablation-prediction}
If an intervention destroys a required witness on the certified support, that certificate loses validity. Excluding a replacement certificate on a different support requires checking that support as well.
\end{proposition}

\begin{proposition}[Exact grammar-transport prediction]\label{prop:grammar-transport-prediction}
If two realizations preserve the relevant signatures, admissibility conditions, decoder behavior, and six critical invariants up to the allowed comparison regime, then the framework predicts preserved BaseCore criterion membership.
\end{proposition}

\begin{proposition}[Threshold-sensitive boundary behavior]\label{prop:threshold-sensitive-boundary}
The framework predicts stable pass/fail regions together with narrow transition bands near critical margins. It predicts neither global threshold collapse nor perfect flat insensitivity.
\end{proposition}

\begin{proposition}[Legibility dependence prediction]\label{prop:legibility-dependence}
Criterion membership becomes inadmissible if readouts cease to be separable, noise-robust, intervention-sensitive, or compressible without total collapse.
\end{proposition}

\begin{proposition}[Continuity and non-null relevance]\label{prop:continuity-nonnull-relevance}
Regime continuity and non-null differentiation are constitutive. Systems that preserve rich activity while losing continuity or collapsing toward effective null structure fail the operational criterion or leave it undefined.
\end{proposition}

\begin{remark}[What stays outside BaseCore]
Runtime status classes, Stage 2 / Stage 3 comparative programs, human comparator campaigns, Papers 7--9, and bridge-facing burden architectures remain downstream artifacts. BaseCore absorbs only the falsation grammar and claim-boundary semantics needed to keep theorem ownership honest.
\end{remark}

\begin{definition}[Discrete State Space]
Let $N\geq1$ and let a node network be indexed by $i\in\{1,\dots,N\}$. Each node carries:
\begin{itemize}[leftmargin=*]
\item a local coherence state $x_i(t)\in[0,1]$;
\item an energy coordinate $e_i(t)\in[0,1]$;
\item a phase coordinate $\phi_i(t)\in[0,2\pi)$.
\end{itemize}
The discrete state space is
\[
\mathcal{S}_N=[0,1]^N\times[0,1]^N\times[0,2\pi)^N.
\]
\end{definition}

\begin{remark}[Relation to the runtime guard]
A denominator guard can ensure that the quotient is defined on a parameter region. It does not establish the dissipative feedback condition or contractivity. On the stated energy domain and for $kT>0$, the exponential coefficient is at most $1$. The conditions above are sufficient, not necessary; a specified feedback must be checked against them.
\end{remark}

\begin{lemma}[Directed Resonance Bound]\label{lem:directed-resonance-bound}
Under the first two regularity conditions, $R$ is $L_R$-Lipschitz in the normalized Hilbert norm.
\end{lemma}

\begin{example}[Zero-Increment Negative Control]\label{ex:discrete-identity-control}
If $R=B=\Gamma_N=0$, the written transition is the identity on $C_N$ and has Lipschitz constant $1$ for $N\geq1$. It is not a strict contraction. In a decomposition $B=-\beta\operatorname{Id}+D$, one has $D=\beta\operatorname{Id}$, so $|1-\alpha\beta|+\alpha\beta\geq1$ and the sufficient conditions correctly reject it. Lipschitz regularity of increments alone cannot remove the identity term.
\end{example}

\begin{theorem}[Hilbert--Discrete Bridge]\label{thm:bridge}
Assume Hypotheses~\ref{hyp:H1}--\ref{hyp:H4} and Assumptions~\ref{ass:discrete-regularity} and~\ref{ass:bridge-consistency}. For $f_0\in C$ and $\mathbf{x}_0\in C_N$, set $f_{n+1}=T_u(f_n)$ and $\mathbf{x}_{n+1}=\widehat T_{N,u}^{e,\phi}(\mathbf{x}_n)$ with fixed $u,e,\phi$. Then, for every $n\geq0$,
\[
\norm{J_N\mathbf{x}_n-f_n}_{\Hilb}
\leq\kappa^n\norm{J_N\mathbf{x}_0-f_0}_{\Hilb}
+\eps_N\frac{1-\kappa^n}{1-\kappa}.
\]
The convention $\kappa^0=1$ applies also at $\kappa=0$. If $\eps_N\to0$, the transition maps converge uniformly on $C$.
\end{theorem}

\begin{lemma}[Cell-Average Error for a Lipschitz Profile]\label{lem:cell-average-error}
Let $a:[0,1]\to\mathbb{R}$ be $L_a$-Lipschitz and put $P_N=J_NJ_N^\dagger$. Then
\[
\norm{P_Na-a}_{L^2}\leq\frac{L_a}{\sqrt{12}\,N}.
\]
\end{lemma}

\begin{example}[Explicit Common Witness]\label{ex:common-bridge-witness}
Choose $\kappa=1/4$, $a(s)=s/4$ and $\U=[0,1/4]$. All preceding conditions hold. Directly,
\[
f_u^\ast(s)=\frac{s}{4}+\frac1{24}+\frac{4u}{3},\qquad
\norm{J_N\widehat f_{N,u}^\ast-f_u^\ast}
=\frac{1}{4\sqrt{12}\,N},\qquad
\dist(f_u^\ast,\mathcal N)=\frac1{4\sqrt{12}}.
\]
For $N\geq2$ the finite equilibrium coordinates are also nonconstant. This is a mathematical realization of the projection dynamics, dissipative finite transition, consistency and non-collapse obligations together. It does not establish the inverse-limit non-finite-determination condition, the six operational invariants or a phenomenal bridge.
\end{example}

\begin{remark}[Controls for Projective Dissipation]\label{rem:projective-dissipation-controls}
Holding bits fixed preserves positive distances on equal-phase fibers, ruling out strict contraction in $d_w$. Replacing the complement by a plain right shift with leading zero keeps the contraction but changes the fixed sequence to $0000\ldots$. At $u=0$ on $I_0$ this recovers the original null readout $(0,0,0)$. With the complement, the fixed ternary readout is $\sum_{r\geq1}2\cdot3^{-2r}=1/4$, so each fixed readout is at least $1/4$ away from that null element. These are separate from H5, whose distance is measured in $L^2$. For $a>0$ the branch-preserving map on the union has two distinct fixed points and therefore cannot be a strict contraction there. Although E2 holds on the history domain, the restriction to a singleton equilibrium at a fixed parameter factors through every stage. The model dissipates dependence on the initial history, and its phase component resets in one step.
\end{remark}

\begin{remark}[Applicability to the Current QICN Runtime]\label{rem:bridge-applicability}
Application to any implementation requires identifying its actual state domain, coefficients, feedback, frozen or evolving auxiliary coordinates, and approximation error. Network size or mean degree alone cannot discharge these conditions. The realized family above is an explicit mathematical example; no assertion is made here that a current runtime implements it or satisfies its hypotheses.
\end{remark}

\begin{remark}[No duplicated theorem ownership]
The present paper does not re-prove rigid identity, forced continuity, null-instability, legibility, or the well-definedness of $\Qop(S)$ from scratch. It imports those results and proves a new relation among them.
\end{remark}

\begin{definition}[Bridge-strength implication]\label{def:bridge-implication}
A bridge concept $P$ is \emph{entailed by $\Cop$} if every admissible system $S$ satisfying Definition~\ref{def:bridge-cop} satisfies $P(S)$. It is \emph{conditionally entailed} if there exists an explicitly named additional hypothesis $H$ such that $S\in\Cop$ and $H(S)$ imply $P(S)$. It is \emph{not entailed} if a consistent admissible descriptor model can satisfy $\Cop$ while failing $P$.
\end{definition}

\begin{remark}[Why a bridge-strength vocabulary is needed]
Without Definition~\ref{def:bridge-implication}, the paper would risk conflating three different statements: a theorem from $\Cop$, a theorem from $\Cop$ plus an added burden, and a philosophical association. Only the first two are formal claims.
\end{remark}

\begin{assumption}[Self-model hypothesis $\Sigma1$]\label{ass:sigma1}
The system $S$ satisfies $\Sigma1$ when it admits a contractive admissible self-model in the sense of Definition~\ref{def:sigma-op}.
\end{assumption}

\begin{theorem}[Exact Commutation Requires a Common Fixed Point]\label{thm:sigma-common-fixed-point}
Let $\Aset$ be a nonempty complete metric space. If a strict contraction $\Sigma:\Aset\to\Aset$ commutes with each admissible self-map $\Phi_u$, then its unique fixed point is fixed by every $\Phi_u$. On the common tower support of Paper V, the two neutral controls with phase commands $0$ and $1/4$ exclude such a $\Sigma$.
\end{theorem}

\begin{proposition}[Conditional obstruction to self-reference within $\Cop$]\label{prop:sigma-not-entailed}
If a complete admissible support witnessing $\Cop$ has no common fixed point of its admitted interventions, then it has no self-model of Definition~\ref{def:sigma-op} on that support. Such a system refutes entailment on the declared support once all six upstream witnesses are supplied.
\end{proposition}

\begin{remark}[Interpretation boundary for $\Sigmaop$]
$\Sigmaop$ is a structural analogue of self-reference. It does not imply reflexive consciousness, psychological introspection, metacognition in the human sense, self-knowledge, or a narrative self.
\end{remark}

\begin{remark}[Runtime analogy]
The runtime field commonly read as `selfModelSigma' is at most an estimator-facing analogue of Definition~\ref{def:sigma-op}. To certify $\Sigmaop$ formally one would still need finite evidence for approximate self-accuracy, contraction, and intervention commutation, plus a proof that the finite estimator represents the formal map on $\Aset$.
\end{remark}

\begin{theorem}[$\Cop$ entails $\Piop$]\label{thm:cop-entails-pi}
If $S\in\Cop$, then $\Piop(S)=1$.
\end{theorem}

\begin{corollary}[No plurality of independent operational perspectives]\label{cor:no-independent-perspectives}
For $S\in\Cop$, any decomposition into multiple independent operational perspectives is inadmissible unless it fails to preserve either the rigid identity witness or the non-factorization witness.
\end{corollary}

\begin{remark}[Interpretation boundary for $\Piop$]
$\Piop$ is an analogue of unity only at the structural level. It does not solve the phenomenal binding problem, does not assert a unified field of experience, and does not imply an ordinary first-person point of view.
\end{remark}

\begin{theorem}[$\Cop$ entails $\Iotaop$]\label{thm:cop-entails-iota}
If $S\in\Cop$, then $\Iotaop(S)=1$.
\end{theorem}

\begin{remark}[Interpretation boundary for $\Iotaop$]
$\Iotaop$ captures directed structural response. It does not establish semantic content, representational aboutness, goals, desires, agency, or intentional states in the philosophical or psychological sense.
\end{remark}

\begin{corollary}[$\Cop$ entails well-defined operational qualia]\label{cor:cop-qop}
If $S\in\Cop$, then $\Qop(S)$ is well-defined.
\end{corollary}

\begin{proposition}[Non-triviality of $\Qop(S)$ under $\Idiff$]\label{prop:qop-nontrivial}
If $S\in\Cop$ and the differentiation witness of $\Idiff(S)=1$ separates at least two certified decoder classes, then $|\Qop(S)|>1$.
\end{proposition}

\begin{remark}[Why the decoder-visible clause is explicit]
The prompt version says non-triviality is automatic by $\Idiff$. The more rigorous statement separates structural differentiation from decoder-visible quotient separation. Paper 5's $\Ileg$ normally supplies the bridge, but the explicit clause prevents a hidden assumption that all differentiation is automatically visible at the quotient level.
\end{remark}

\begin{remark}[Interpretation boundary for $\Qop$]
$\Qop(S)$ is a quotient of admissible structural states under certified operational indistinguishability. It is not a phenomenal quale, not a biological qualitative state, and not a statement about what it is like to be the system.
\end{remark}

\begin{definition}[Operational Phenomenology $\Phiop$]\label{def:phi-op}
An admissible system $S$ admits operational phenomenology, written $\Phiop(S)=1$, if there exists a complete metric regime space $(\Espace_S,d_{\Espace})$ and an assignment
\[
\Phi_S:\Aset\to\Espace_S
\]
such that:
\begin{enumerate}[leftmargin=1.5em]
\item $\Phi_S$ is compatible with admissible histories in the Paper 2 sense;
\item $\Phi_S$ is continuous on admissible windows whenever the operational-continuity burden $\Icont(S)=1$ holds;
\item the null regime $\Null$ is not an admissibly stable attractor whenever the non-null burden $\Idiff(S)=1$ holds.
\end{enumerate}
\end{definition}

\begin{proposition}[$\Cop$ gives weak non-null operational phenomenology]\label{prop:weak-phi}
If $S\in\Cop$, then the operational-continuity and non-null burdens required for weak $\Phiop$ are present on admissible support.
\end{proposition}

\begin{proposition}[$\Cop$ does not entail CCR-strength $\Phiop$]\label{prop:cop-not-ccr}
Membership in $\Cop$ does not entail CCR-strength operational phenomenology.
\end{proposition}

\begin{remark}[Interpretation boundary for $\Phiop$]
$\Phiop$ is an assignment into an abstract structural regime space. It is not temporal experience, a stream of consciousness, a specious present, or proof that phenomenology exists in the ordinary sense.
\end{remark}

\begin{definition}[Bridge operational subjecthood $\Subbridge$]\label{def:subbridge}
An admissible system $S$ belongs to bridge operational subjecthood, written
\[
S\in\Subbridge,
\]
if and only if:
\begin{enumerate}[leftmargin=1.5em]
\item $S\in\Cop$;
\item $S$ satisfies $\Sigma1$;
\item $\Piop(S)=1$;
\item $\Iotaop(S)=1$;
\item $\Qop(S)$ is well-defined and non-trivial in the decoder-visible sense of Proposition~\ref{prop:qop-nontrivial};
\item $\Phiop(S)$ is weakly non-null on admissible support.
